full/powershell/vscode/ollama-embed/open.copy:
# Keep generated configuration files out of version control.
if (-not (Test-Path .gitignore)) { New-Item -ItemType File -Path .gitignore | Out-Null }
Add-Content -Path .gitignore -Value '.chunkhound.json'
# Configure ChunkHound with Ollama embeddings and OpenRouter for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
# You'll need: OpenRouter API key
@'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "openrouter",
    "model": "poolside/laguna-s-2.1",
    "api_key": "<YOUR_OPENROUTER_API_KEY>"
  }
}
'@ | Set-Content -Path '.chunkhound.json' -Encoding utf8

# Configure VS Code to connect to ChunkHound via MCP.
if (Test-Path '.vscode/mcp.json') {
Write-Host @'
.vscode/mcp.json already exists — merge this block into it manually:
{
  "servers": {
    "ChunkHound": {
      "type": "stdio",
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
'@
} else {
New-Item -ItemType Directory -Force -Path '.vscode' | Out-Null
@'
{
  "servers": {
    "ChunkHound": {
      "type": "stdio",
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
'@ | Set-Content -Path '.vscode/mcp.json' -Encoding utf8
}

